using eWolfBootstrap.Builders;
using eWolfBootstrap.SiteBuilder;
using eWolfBootstrap.SiteBuilder.Attributes;
using eWolfBootstrap.SiteBuilder.Enums;
using eWolfSiteBuilder.Helpers;

namespace eWolfSiteBuilder._Site.Games.NumberTrail
{
    [PageTitle("index.html")]
    public class Index : PageDetailsWolfSite
    {
        private const string HeaderImage = "FeatureGraphic-1024x500.png";
        private const string ImageFolder = "Images";
        private const string PlayStoreLink = "https://play.google.com/store/apps/details?id=com.numbertrail.game";

        /// <summary>Hand-written, not generated — it lives beside the generated index.html.</summary>
        private const string PrivacyPolicyPage = "privacy-policy.html";

        /// <summary>
        /// The listing does not exist yet, so a live store button would 404. Flip this to
        /// true on the day it goes live and both buttons start working.
        /// </summary>
        private static readonly bool Released = false;

        /// <summary>
        /// Artwork lives in DemoSite/Games/NumberTrail/Images and is not generated by the
        /// builder. Turn this off again if the folder is ever emptied: the hero image and the
        /// screenshot grid are then skipped rather than rendered as broken images.
        /// </summary>
        private static readonly bool ImagesReady = true;

        /// <summary>
        /// The same five images used on the Play Store listing, so the two places a stranger
        /// might meet this game show it identically.
        ///
        /// Captures come from the game itself: press C while playing in the Unity editor and
        /// a timestamped PNG lands in C:\Unity3d\NumberTrail\ScreenShots, which is then run
        /// through Tools\MakeStoreScreenshotTilted.ps1 to add the device frame and caption.
        /// A sixth showing Challenging's number gaps is still missing -- the only capture of
        /// it so far has a board with no gaps on it, which the caption would contradict.
        /// </summary>
        private static readonly (string File, string Caption)[] Screenshots = new (string, string)[]
        {
            ("ss-trace-the-numbers.png", "Trace the numbers in order, without lifting your finger"),
            ("ss-beat-the-clock.png", "The clock never stops, and it tightens as you climb"),
            ("ss-route-around-the-blanks.png", "Blank decoys are not part of the chain — go around them"),
            ("ss-a-new-set-every-day.png", "A new daily set each day, with your last seven results"),
            ("ss-spare-seconds-become-points.png", "Finish early and the time left becomes points"),
        };

        public Index()
        {
            WebPage = new WebPage(this);
            DisplayTitle = "Number Trail";
            MenuTitle = "Number Trail";
            Keywords.Add(DisplayTitle);
            Keywords.AddRange(
                 new string[]
                 {
                    "number puzzle game",
                    "connect the numbers",
                    "android puzzle game",
                    "daily puzzle",
                    "brain training"
                 });
        }

        public override void CreatePage()
        {
            WebPage.AddHeader(this, string.Empty);
            WebPage.AddNavigation(NavigationTypes.Main, @"../../");
            WebPage.StartBody();

            WebPage.StartDiv("<div class='container mt-12'>");

            WebPage.Append(CreateHero());
            WebPage.Append(CreateDescription());
            WebPage.Append(CreateScreenShots());

            WebPage.CloseAllsDiv();
            WebPage.EndBody();
            WebPage.Output();
        }

        private void AddScreenShot(HTMLSection section, string imageName, string caption)
        {
            section.ImagePath($"{ImageFolder}/{imageName}", 90);
            section.StartTextCenter();
            section.Text(caption);
            section.EndTextCenter();
            section.NewLine();
        }

        private string CreateDescription()
        {
            HTMLBuilder outer = new HTMLBuilder();

            outer.StartTextCenter();
            outer.Text("A one line puzzle game for Android. Numbered coins drift across the board, and the job is to trace them in order without lifting your finger.");
            outer.NewLine();
            outer.Text("Touch the wrong coin and the whole trail breaks, and you start the chain again with the clock still running.");
            outer.NewLine();
            outer.NewLine();
            outer.Text("Beat the timer and every spare second is added to your score. Run it out and it costs you a life.");
            outer.NewLine();
            outer.NewLine();
            outer.EndTextCenter();

            outer.InspectorDetails("Three ways to play", "Level runs the numbers in order, Challenging leaves gaps in the sequence, and Daily gives every player the same ten boards");
            outer.InspectorDetails("A new set every day", "Ten daily levels built from the date, identical for everyone, with the last seven days of results kept on the menu — green for passed, red for failed, grey for not played");
            outer.InspectorDetails("Find it, do not count to it", "Challenging widens the gaps as you climb, so you are hunting the next number rather than counting up to it");
            outer.InspectorDetails("Decoys in the way", "Blank, unnumbered coins start appearing early on. They are not part of the chain, so the line has to go around them");
            outer.InspectorDetails("It keeps getting harder", "Five coins become ten, the clock tightens every couple of levels, and later on the coins stop holding still and drift while you trace");
            outer.InspectorDetails("Three lives", "Running the clock out costs one, and the run ends when the last one goes");
            outer.InspectorDetails("Beat the clock for a bonus", "Finish early and the time left on the timer is converted straight into points");
            outer.InspectorDetails("See where the points went", "Every finished level is itemised — coins, level bonus, time bonus, and what a broken trail cost you");
            outer.InspectorDetails("Fair by construction", "Boards are generated so the correct path never passes within touch range of a coin that would break it, and every level is stress tested after any change to the rules");
            outer.InspectorDetails("Built for one hand", "Portrait, one finger, no account and no sign-up. Most runs take a few minutes");

            outer.NewLine();
            outer.NewLine();
            outer.StartTextCenter();
            outer.Text(Released
                ? "Number Trail is free to download and play on any Android phone or tablet."
                : "Number Trail is finished and in testing. It will be free to download and play on any Android phone or tablet.");
            outer.NewLine();
            outer.NewLine();
            outer.Text(PlayStoreButton());
            outer.NewLine();
            outer.NewLine();

            // Play requires a publicly reachable privacy policy URL for any app that serves
            // ads, and this page is the only public place it lives. The file sits beside this
            // one in the same folder, so the link is relative and cannot rot.
            outer.Text($"<a href='{PrivacyPolicyPage}'>Privacy policy</a>");
            outer.NewLine();
            outer.EndTextCenter();

            return outer.Output();
        }

        private string CreateHero()
        {
            HTMLBuilder outer = new HTMLBuilder();

            if (ImagesReady)
            {
                outer.ImagePath($"{ImageFolder}/{HeaderImage}", 100);
                outer.NewLine();
            }

            outer.Jumbotron(DisplayTitle, Released
                ? "One line, one to ten, one shot at it. Out now on Google Play."
                : "One line, one to ten, one shot at it. Coming soon to Google Play.");

            outer.StartTextCenter();
            outer.Text(PlayStoreButton());
            outer.NewLine();
            outer.EndTextCenter();

            return outer.Output();
        }

        private string CreateScreenShots()
        {
            if (!ImagesReady || Screenshots.Length == 0)
                return string.Empty;

            HTMLBuilder outer = new HTMLBuilder();

            outer.StartTextCenter();
            outer.Text("<h3>Screen shots</h3>");
            outer.NewLine();
            outer.EndTextCenter();

            // Three to a row, matching the other game pages. A partial last row is fine;
            // the unused sections simply render nothing.
            for (int i = 0; i < Screenshots.Length; i += 3)
            {
                HTMLBuilder options = new HTMLBuilder();
                HTMLSection a = new HTMLSection("col-md-4");
                HTMLSection b = new HTMLSection("col-md-4");
                HTMLSection c = new HTMLSection("col-md-4");
                options.SetThreeSections(a, b, c);

                HTMLSection[] row = new[] { a, b, c };
                for (int column = 0; column < 3 && i + column < Screenshots.Length; column++)
                {
                    AddScreenShot(row[column], Screenshots[i + column].File, Screenshots[i + column].Caption);
                }

                outer.Text(options.Output());
                outer.NewLine();
            }

            return outer.Output();
        }

        private string PlayStoreButton()
        {
            if (!Released)
                return "<span class='btn btn-secondary btn-lg disabled'>Coming soon to Google Play</span>";

            return $"<a href='{PlayStoreLink}' target='_blank' class='btn btn-success btn-lg'>Get it on Google Play</a>";
        }
    }
}
